import pandas as pd
from datetime import timedelta

def run(inputs: dict) -> dict:
    df = inputs["device_sessions"].copy()

    if df.empty:
        return {"merged_sessions": pd.DataFrame(columns=[
            "user_id", "merged_num", "start_ts", "end_ts",
            "device_count", "source_count"
        ])}

    df = df.sort_values(by=["user_id", "start_ts", "end_ts", "session_id"],
                         kind="mergesort")

    records = []

    for user_id, group in df.groupby("user_id", sort=False):
        group = group.sort_values(by=["start_ts", "end_ts", "session_id"],
                                   kind="mergesort")

        merged_num = 0
        group_start = None
        group_end = None
        device_ids = set()
        source_count = 0

        for row in group.itertuples(index=False):
            start_ts = row.start_ts
            end_ts = row.end_ts
            device_id = row.device_id

            if group_end is None:
                # open first group
                group_start = start_ts
                group_end = end_ts
                device_ids = {device_id}
                source_count = 1
            else:
                threshold = group_end + timedelta(minutes=5)
                if start_ts <= threshold:
                    if end_ts > group_end:
                        group_end = end_ts
                    device_ids.add(device_id)
                    source_count += 1
                else:
                    merged_num += 1
                    records.append({
                        "user_id": user_id,
                        "merged_num": merged_num,
                        "start_ts": group_start,
                        "end_ts": group_end,
                        "device_count": len(device_ids),
                        "source_count": source_count
                    })
                    group_start = start_ts
                    group_end = end_ts
                    device_ids = {device_id}
                    source_count = 1

        if group_end is not None:
            merged_num += 1
            records.append({
                "user_id": user_id,
                "merged_num": merged_num,
                "start_ts": group_start,
                "end_ts": group_end,
                "device_count": len(device_ids),
                "source_count": source_count
            })

    result = pd.DataFrame.from_records(records, columns=[
        "user_id", "merged_num", "start_ts", "end_ts",
        "device_count", "source_count"
    ])

    return {"merged_sessions": result}
